_LEVY = {
    "grid_fee": ("Netzentgelt", "Entgelt für die Nutzung des Stromnetzes"),
    "electricity_tax": ("Stromsteuer", "Steuer auf den Stromverbrauch"),
    "concession_fee": ("Konzessionsabgabe", "Abgabe an die Kommune für die Nutzung öffentlicher Wege"),
    "kwk_levy": ("KWK-Aufschlag", "Umlage zur Förderung der Kraft-Wärme-Kopplung"),
    "stromnev19_levy": ("StromNEV-§19-Umlage", "Umlage für Netzentgeltprivilegien nach §19 StromNEV"),
    "offshore_levy": ("Offshore-Netzumlage", "Umlage für die Netzanbindung von Offshore-Windparks"),
}
for _key, (_name, _what) in _LEVY.items():
    for _side, _who in (("ely", "den Elektrolyseur"), ("rest", "die übrigen Verbraucher (Peripherie und Verdichter)")):
        HELP[f"levy_{_side}_{_key}_ct_per_kwh"] = (
            f"{_name} ({_what}) in ct je kWh für {_who}. Der Wert wird nur angesetzt, wenn keine Befreiung angekreuzt ist.")
        HELP[f"levy_{_side}_{_key}_exempt"] = (
            f"Ankreuzen, wenn {_who} vom {_name} befreit {'ist' if _side == 'ely' else 'sind'}. "
            "Die Befreiung wird als Privilegierung in der Ergebnisauswertung ausgewiesen.")
